package android.content;import java.util.*;public class ClipData {public static class Item {private android.net.Uri uri;public Item(android.net.Uri u){uri=u;}public android.net.Uri getUri(){return uri;}}private List<Item> items=new ArrayList<>();public ClipData(CharSequence label,String[] mime,Item item){items.add(item);}public static ClipData newRawUri(CharSequence label,android.net.Uri u){return new ClipData(label,new String[]{"*/*"},new Item(u));}public void addItem(Item i){items.add(i);}public int getItemCount(){return items.size();}public Item getItemAt(int n){return items.get(n);}}